//! Clip-level command rows: properties, transforms, parameters, audio,
//! styling, effects, transitions, and clip-scoped structural edits.

macro_rules! clip_rows {
    ($next:path, $($accum:tt)*) => {
        $next! {
            $($accum)*
            addresses clip {
                FreezeFrame { label: "Freeze frame", reach: operator("the clip context menu's Freeze Frame item, and the Sequence menu"), junctions: breaks, lock: guarded,
                    undo: restores("removes the held frame and rejoins the source clip it split"), },
                BakeClip { label: "Render and replace", reach: operator("the Sequence menu's Render And Replace row"), junctions: keeps, lock: guarded,
                    undo: restores("the clip as it was before it was rendered"), },
                RestoreBakedClip { label: "Restore unrendered", reach: operator("the palette's Restore Unrendered row"), junctions: keeps, lock: guarded,
                    undo: restores("the rendered file in the clip's place"), },
                SetGenerator { label: "Edit generator", reach: operator("the inspector's Text block: the content field and the text presets"), junctions: keeps, lock: guarded,
                    undo: restores("the previous generator content"), },
                SetClipMedia { label: "Replace clip media", reach: operator("the inspector's Template block, and a media drop onto a marked slot"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous media and source window"), },
                SetReplaceable { label: "Mark replaceable", reach: operator("the palette's template-slot row"), junctions: keeps, lock: guarded,
                    undo: restores("the previous template-slot marker"), },
                SetTextEditable { label: "Mark text editable", reach: operator("the inspector's Template block"), junctions: keeps, lock: guarded,
                    undo: restores("the previous text-editable flag"), },
                PasteAttributes { label: "Paste attributes", reach: operator("the Edit menu's Paste Attributes row"), junctions: keeps, lock: guarded,
                    undo: restores("the target clip's previous transform, filter, and effect chain"), },
                RemoveAttributes { label: "Remove attributes", reach: operator("the Edit menu's Remove Attributes dialog"), junctions: keeps, lock: guarded,
                    undo: restores("the clip as it was, every removed group and its duration included"), },
                SetClipTransform { label: "Transform", reach: operator("the transform handles on the preview, and the inspector's Transform fields"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous transform, keyframes included"), },
                SetClipParent { label: "Set parent", reach: operator("the clip context menu's Release Parent row, and the inspector's Transform block: the Parent row's menu and its pick whip, Shift held to snap"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parent and transform"), },
                SetParamKeyframe { label: "Set keyframe", reach: operator("the palette's keyframe rows, and the inspector's stopwatch on every animatable row"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state"), },
                RemoveParamKeyframe { label: "Remove keyframe", reach: operator("the inspector's keyframe list, and the stopwatch on a keyed row"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state, so the removed keyframe returns"), },
                SetParamDriver { label: "Set driver", reach: operator("the inspector's keyframe list: the driver button on a property's row, or Alt+click on its stopwatch, adds a driver and a second press removes it; the driver row under the property edits it, and its pick whip inserts references"), junctions: keeps, lock: guarded,
                    undo: restores("the property's previous driver, or none"), },
                SetParamConstant { label: "Set parameter", reach: operator("the inspector's parameter fields and colour wheels, and flattening a keyed row"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state, dropped keyframes included"), },
                ApplyEasingPreset { label: "Apply easing", reach: operator("the inspector's keyframe list: the easing presets on a selected segment"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state, so the expanded segment collapses"), },
                SetClipSpeed { label: "Set speed", reach: operator("the inspector's Speed block, and the rate-stretch drag on the timeline"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous speed, direction and derived duration"), },
                SetSpeedCurve { label: "Set speed curve", reach: operator("the inspector's Speed block: the ramp presets and the curve editor"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous ramp and derived duration"), },
                SetClipPitch { label: "Set pitch lock", reach: operator("the palette's Pitch Lock row"), junctions: keeps, lock: guarded,
                    undo: restores("the previous pitch-preservation flag"), },
                SetClipCrop { label: "Crop", reach: operator("the palette's flip and crop-reset rows, the crop handles on the preview, and the inspector's Crop fields"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous crop rect and flips"), },
                SetClipAudio { label: "Set audio levels", reach: operator("the inspector's Audio block: the volume nudge and the two fade fields, and the two fade handles on the timeline"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous gain and fades"), },
                SetClipDenoise { label: "Set denoise", reach: operator("the palette's Denoise row"), junctions: keeps, lock: guarded,
                    undo: restores("the previous noise-reduction flag"), },
                SetClipLabel { label: "Set label colour", reach: operator("the clip context menu's label colours"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous label colour"), },
                SetClipName { label: "Rename clip", reach: operator("the rename bar, opened from the clip context menu or a double click on the card"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous name"), },
                SetClipType { label: "Set clip type", reach: operator("placing a plugin clip type from the Generators tab or the palette, and the inspector's Detach"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous type"), },
                SetClipLineParam { label: "Show property on clip", reach: operator("the fx badge's context menu on a timeline clip bar"), junctions: keeps, lock: guarded,
                    undo: restores("the property the clip's bar drew before"), },
                AddClipMask { label: "Add mask", reach: operator("the Look block's mask shape buttons, the palette's Add mask rows, and a mask dropped from the catalog"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's mask stack without the added mask"), },
                SetClipMask { label: "Set mask", reach: operator("the Look block's mode and invert buttons, and the mask handles on the preview"), junctions: keeps, lock: guarded,
                    undo: restores("the mask's previous shape, mode and path"), },
                RemoveClipMask { label: "Remove mask", reach: operator("the Look block's remove button, the palette's Remove mask row, and the Effect menu's Remove Mask row"), junctions: keeps, lock: guarded,
                    undo: restores("the removed mask and the drivers on it"), },
                MoveClipMask { label: "Reorder masks", reach: operator("the Look block's move up and move down buttons"), junctions: keeps, lock: guarded,
                    undo: restores("the mask stack's previous order"), },
                SetClipBlendMode { label: "Set blend mode", reach: operator("the inspector's Grade block: the blend mode picker"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous blend mode"), },
                SetClipMotionBlur { label: "Set motion blur", reach: operator("the palette's Motion Blur row"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous motion blur"), },
                SetClipLayerStyles { label: "Set layer styles", reach: operator("the inspector's Styles block: the shadow, glow, outline and background rows"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous layer styles"), },
                SetClipChroma { label: "Set chroma key", reach: operator("the palette's chroma-key rows"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous chroma key"), },
                SetClipMatte { label: "Set track matte", reach: operator("the palette's track-matte rows"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous track matte"), },
                SetClipStabilize { label: "Stabilize", reach: operator("the inspector's Grade block: the stabilization picker"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous stabilization level"), },
                SetClipFilter { label: "Set filter", reach: operator("the inspector's Look block: the filter picker and its intensity"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous filter"), },
                SetClipLut { label: "Set LUT", reach: operator("the inspector's Styles block: the LUT picker"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous LUT"), },
                SetClipAdjustments { label: "Grade", reach: operator("the palette's Reset Grade row, and the inspector's grade sliders and wheels"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous colour adjustments"), },
                SetClipAnimation { label: "Set animation", reach: operator("the inspector's Animation block, and dragging an animation from the sidebar onto a clip"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous animation slots, including the side a combo replaced"), },
                SetAudioRole { label: "Set audio role", reach: operator("the inspector's Audio block: the role picker"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous audio role"), },
                AddEffect { label: "Add effect", reach: operator("the inspector's Effects block: the add-effect picker"), junctions: keeps, lock: guarded,
                    undo: restores("the chain without the appended effect"), },
                RemoveEffect { label: "Remove effect", reach: operator("the inspector's Effects block: the remove button on each row"), junctions: keeps, lock: guarded,
                    undo: restores("the removed effect at its index, with its parameter values"), },
                MoveEffect { label: "Reorder effect", reach: operator("the inspector's Effects block: the up and down arrows on each row"), junctions: keeps, lock: guarded,
                    undo: restores("the chain's previous order, instance for instance"), },
                SetEffectParam { label: "Set effect parameter", reach: operator("the inspector's Effects block: each parameter's slider, colour and vec2 fields"), junctions: keeps, lock: guarded,
                    undo: restores("the effect's previous parameter value"), },
                SetEffectInstance { label: "Update effect parameters", reach: operator("the inspector's Effects block: each parameter's toggle, choice, curve, gradient, text, font, file and layer fields"), junctions: keeps, lock: guarded,
                    undo: restores("the effect's previous parameter state"), },
                SetEffectBypass { label: "Bypass effect", reach: operator("the inspector's Effects block: the fx toggle on each effect header"), junctions: keeps, lock: guarded,
                    undo: restores("the effect's previous bypass state"), },
                ApplyPreset { label: "Apply preset", reach: operator("the inspector's Effects block: the saved-preset rows"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous effect chains and animated parameters"), },
                AddTransition { label: "Add transition", reach: operator("the clip context menu's transition items"), junctions: keeps, lock: guarded,
                    undo: restores("the lane's transitions without the added junction"), },
                RemoveTransition { label: "Remove transition", reach: operator("the clip context menu's Remove Transition item"), junctions: keeps, lock: guarded,
                    undo: restores("the removed junction with its length"), },
                SetTransition { label: "Set transition length", reach: operator("dragging a transition's edge on the timeline"), junctions: keeps, lock: guarded,
                    undo: restores("the junction's previous length"), },
                SetTransitionAlignment { label: "Set transition alignment", reach: operator("the inspector's Transition block and the transition context menu"), junctions: keeps, lock: guarded,
                    undo: restores("the junction's previous alignment"), },
                SetTransitionState { label: "Set transition parameters", reach: operator("the inspector's transition parameter fields"), junctions: keeps, lock: guarded,
                    undo: restores("the junction's previous transition state"), },
                SplitClip { label: "Split clip", reach: operator("the palette's Split row and the split chord"), junctions: breaks, lock: guarded,
                    undo: restores("the single clip, dropping both halves"), },
                TrimClip { label: "Trim clip", reach: operator("the trim-in and trim-out chords, and dragging a clip edge on the timeline"), junctions: breaks, lock: guarded,
                    undo: restores("the clip's previous timeline placement and source window"), },
                TrimClipUnlinked { label: "Trim clip without links", reach: operator("the trim-in and trim-out chords with linked selection off, and dragging a clip edge on the timeline with it off"), junctions: breaks, lock: guarded,
                    undo: restores("the clip's previous timeline placement and source window"), },
                SlipClip { label: "Slip clip", reach: operator("the slip drag on the timeline, with the slip tool"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous source window"), },
                RemoveClip { label: "Delete clip", reach: operator("the clip context menu's Delete item, and the Edit menu"), junctions: breaks, lock: guarded,
                    undo: restores("the clip on its lane, at the placement it had"), },
                RippleDelete { label: "Ripple delete", reach: operator("the palette's Delete row and the delete chords"), junctions: breaks, lock: guarded,
                    undo: restores("the clip and re-opens the gap the lane closed behind it"), },
                SetClipBeats { label: "Set beats", reach: operator("the beat-detection job, queued from the analysis panel, writing what it found"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous beat grid"), },
                ClearBeats { label: "Clear beats", reach: operator("the analysis panel's clear button"), junctions: keeps, lock: guarded,
                    undo: restores("the beat grid that was cleared"), },
                SetKeyframeEase { label: "Set keyframe ease", reach: operator("the keyframe list, the graph editor's influence handles, and the easy-ease and hold chords"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state"), },
                SetKeyframeRoving { label: "Set roving keyframe", reach: operator("the keyframe list and the keyframe context menu's Rove Across Time toggle"), junctions: keeps, lock: guarded,
                    undo: restores("the clip's previous parameter state, including the keyframe's anchored tick"), },
            }

            addresses clip_and_lane {
                DuplicateClip { label: "Duplicate clip", reach: operator("the duplicate chord, and the clip context menu"), junctions: breaks, lock: guarded,
                    undo: restores("nothing of the original; it removes the copy"), },
                PasteRetimed { label: "Paste retimed", reach: operator("the Edit menu's Paste To Fit row, over a marked range"), junctions: breaks, lock: guarded,
                    undo: restores("nothing of the original; it removes the copy"), },
                MoveClip { label: "Move clip", reach: operator("dragging a clip on the timeline, and the step chords"), junctions: breaks, lock: guarded,
                    undo: restores("the clip's previous lane and start"), },
                MoveClipUnlinked { label: "Move clip without links", reach: operator("the step chords with linked selection off, and dragging a clip on the timeline with it off"), junctions: breaks, lock: guarded,
                    undo: restores("the clip's previous lane and start"), },
                RippleMoveClip { label: "Ripple move clip", reach: operator("Shift-dragging a clip on the timeline"), junctions: breaks, lock: guarded,
                    undo: restores("the clip's previous lane and start, and the gap it closed"), },
            }

            addresses clip_and_optional_lane {
                ExtractAudio { label: "Extract audio", reach: operator("the clip context menu's Extract Audio item, and the Sequence menu"), junctions: keeps, lock: guarded,
                    undo: restores("nothing of the source clip; it removes the companion, the lane if one was created, and the link"), },
            }

            addresses clips {
                LinkClips { label: "Link clips", reach: operator("the clip context menu's Link item, and the Sequence menu"), junctions: keeps, lock: guarded,
                    undo: restores("the clips' previous link groups"), },
                UnlinkClips { label: "Unlink clips", reach: operator("the palette's Unlink row, and the clip context menu"), junctions: keeps, lock: guarded,
                    undo: restores("every link group that was dissolved"), },
                SetClipsEnabled { label: "Set clips enabled", reach: operator("the Clip menu's Enable row, the clip context menu, and the palette"), junctions: keeps, lock: guarded,
                    undo: restores("each clip's previous enabled state"), },
                GroupClips { label: "Group clips", reach: operator("the Clip menu's Group row, the clip context menu, and the palette"), junctions: keeps, lock: guarded,
                    undo: restores("the clips' previous groups"), },
                UngroupClips { label: "Ungroup clips", reach: operator("the Clip menu's Ungroup row, the clip context menu, and the palette"), junctions: keeps, lock: guarded,
                    undo: restores("every clip group that was dissolved"), },
                CreateNestedSequence { label: "Nest sequence", reach: operator("the palette's Nest Selection row, and the Sequence menu"), junctions: breaks, lock: guarded,
                    undo: restores("the original clips on their tracks and removes the nested sequence"), },
            }
        }
    };
}

pub(super) use clip_rows;
